<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { buscarProveedorRuc, guardarProforma, listarProformas, seleccionarPrecio, type EvaluacionProforma, type ItemProforma, type Proforma, type ProveedorCotizacion } from '../services/proformas'
const evaluations=ref<EvaluacionProforma[]>([]),selectedEvaluation=ref<number|null>(null),items=ref<ItemProforma[]>([]),quotes=ref<Proforma[]>([]),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),ruc=ref(''),provider=ref<ProveedorCotizacion|null>(null),prices=ref<Record<number,number>>({}),form=reactive({fecha_vencimiento:''})
const current=computed(()=>evaluations.value.find(x=>x.id===selectedEvaluation.value)),total=computed(()=>items.value.reduce((sum,x)=>sum+x.cantidad*(prices.value[x.item_id]||0),0))
async function load(id=selectedEvaluation.value){loading.value=true;error.value='';try{const r=await listarProformas(id);evaluations.value=r.evaluaciones;items.value=r.items;quotes.value=r.proformas;if(!selectedEvaluation.value&&r.evaluaciones[0]){selectedEvaluation.value=r.evaluaciones[0].id;await load(selectedEvaluation.value)}}catch(e){error.value=message(e)}finally{loading.value=false}}
async function selectEvaluation(){await load(selectedEvaluation.value)}
function open(){provider.value=null;ruc.value='';prices.value={};form.fecha_vencimiento='';modal.value=true}
async function findProvider(){if(!/^\d{11}$/.test(ruc.value)){error.value='Ingrese un RUC válido de 11 dígitos.';return}try{provider.value=await buscarProveedorRuc(ruc.value)}catch(e){provider.value=null;error.value=message(e)}}
async function save(){if(!selectedEvaluation.value||!provider.value)return;if(!form.fecha_vencimiento){error.value='Ingrese la fecha de vencimiento.';return}const lines=items.value.map(x=>({item_id:x.item_id,cantidad:x.cantidad,precio_unitario:prices.value[x.item_id]||0}));if(!lines.some(x=>x.precio_unitario>0)){error.value='Ingrese al menos un precio unitario.';return}saving.value=true;try{await guardarProforma(selectedEvaluation.value,{proveedor_id:provider.value.id,fecha_vencimiento:form.fecha_vencimiento,items:lines});modal.value=false;success.value='Proforma registrada correctamente.';await load()}catch(e){error.value=message(e)}finally{saving.value=false}}
async function choose(lineId:number){if(!selectedEvaluation.value||!confirm('¿Seleccionar este precio para el ítem?'))return;try{await seleccionarPrecio(selectedEvaluation.value,lineId);success.value='Precio seleccionado correctamente.';await load()}catch(e){error.value=message(e)}}
const money=(v=0)=>new Intl.NumberFormat('es-PE',{style:'currency',currency:'PEN'}).format(v),message=(e:unknown)=>e instanceof Error?e.message:'No se pudo completar la operación.';onMounted(()=>load(null))
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Logística / Proformas</nav><header class="hero"><div class="mark">PF</div><div><small>MIA · COTIZACIONES</small><h1>Proformas</h1><p>Registra cotizaciones y selecciona precios por producto.</p></div><select v-model="selectedEvaluation" @change="selectEvaluation"><option :value="null">Seleccione evaluación</option><option v-for="x in evaluations" :key="x.id" :value="x.id">#{{x.id}} · {{x.nombre}}</option></select><button :disabled="!selectedEvaluation" @click="open">+ Agregar proforma</button></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash">{{error}}</p><div v-if="loading" class="empty">Cargando proformas…</div><div v-else-if="!selectedEvaluation" class="empty">Seleccione una evaluación para consultar sus cotizaciones.</div><template v-else><section class="summary"><div><small>EVALUACIÓN</small><b>{{current?.nombre}}</b><span>{{current?.proceso}}</span></div><div><small>ÍTEMS</small><b>{{items.length}}</b></div><div><small>PROFORMAS</small><b>{{quotes.length}}</b></div><div><small>ESTADO</small><b>{{current?.estado_nombre}}</b></div></section>
<section class="layout"><main><header><div><small>COMPARACIÓN DE PRECIOS</small><h2>Ítems en evaluación</h2></div></header><article v-for="item in items" :key="item.item_id" class="item"><div class="item-head"><img v-if="item.imagen_url" :src="item.imagen_url" alt=""><div v-else class="no-image">📦</div><div><small>ÍTEM #{{item.item_id}}</small><h3>{{item.nombre}}</h3><span>{{item.cantidad}} {{item.unidad}}</span></div></div><table><thead><tr><th>Proveedor</th><th>Precio unitario</th><th>Subtotal</th><th>Vigencia</th><th></th></tr></thead><tbody><tr v-for="price in item.precios" :key="price.detalle_id" :class="{selected:price.seleccionado}"><td>{{price.ruc}} · {{price.proveedor}}</td><td>{{money(price.precio_unitario)}}</td><td>{{money(price.subtotal)}}</td><td>{{quotes.find(x=>x.id===price.proforma_id)?.fecha_vencimiento}}</td><td><b v-if="price.seleccionado">★ SELECCIONADO</b><button v-else-if="price.precio_unitario>0" @click="choose(price.detalle_id)">Seleccionar</button></td></tr><tr v-if="!item.precios.length"><td colspan="5">Sin precios registrados.</td></tr></tbody></table></article></main><aside><header><small>PROVEEDORES COTIZADOS</small><h2>Proformas registradas</h2></header><article v-for="quote in quotes" :key="quote.id"><div><b>{{quote.proveedor}}</b><span>RUC {{quote.ruc}}</span></div><em :class="{expired:!quote.vigente}">{{quote.vigente?'Vigente':'Vencida'}}</em><strong>{{money(quote.total)}}</strong><small>Vence: {{quote.fecha_vencimiento}}</small></article><div v-if="!quotes.length" class="mini-empty">Aún no hay proformas.</div></aside></section></template>
<div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="save"><header><div><small>PASO 1 · PROVEEDOR</small><h2>Registrar proforma</h2></div><button type="button" @click="modal=false">×</button></header><section class="provider-search"><label>RUC del proveedor *<span><input v-model.trim="ruc" inputmode="numeric" maxlength="11" placeholder="Ingrese 11 dígitos"><button type="button" @click="findProvider">Buscar</button></span></label><div v-if="provider"><b>{{provider.razon_social}}</b><span>RUC {{provider.ruc}}</span></div></section><template v-if="provider"><label>Fecha de vencimiento *<input v-model="form.fecha_vencimiento" type="date"></label><h3>Precios unitarios</h3><div class="price-lines"><div v-for="item in items" :key="item.item_id"><span>{{item.nombre}}</span><small>{{item.cantidad}} {{item.unidad}}</small><input v-model.number="prices[item.item_id]" type="number" min="0" step="0.01" placeholder="Precio unitario"><b>{{money(item.cantidad*(prices[item.item_id]||0))}}</b></div></div><footer><b>Total {{money(total)}}</b><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':'Registrar proforma'}}</button></footer></template></form></div></div></template>
